// NodeMemoryReport: How much memory one node uses against its limits, which the node publishes with
// every heartbeat so that the cluster stops taking writes before the node runs out of memory.
type NodeMemoryReport struct {
	// The whole process holds this many bytes of resident memory, including vectors and segments kept
	// outside the heap.
	ProcessBytes float64 `json:"processBytes"`
	// The process may hold this many bytes. Where a container sets a memory limit, this figure is that
	// limit. Without one, a node on Linux reports its own resident memory plus the memory that the host
	// reports as available, up to the host's total memory, so the figure falls whenever other processes on
	// the host take memory. A node on any other system reports the host's total memory.
	ProcessLimitBytes float64 `json:"processLimitBytes"`
	// The main thread's old generation uses this many bytes. The old generation is the V8 heap without the
	// young generation, which holds new objects until the collector empties it.
	HeapBytes float64 `json:"heapBytes"`
	// The main thread's old generation may grow to this many bytes. This is the `--max-old-space-size`
	// figure where the process sets it, and otherwise V8's heap limit less the young generation's share.
	HeapLimitBytes float64 `json:"heapLimitBytes"`
	// This is true while the node refuses writes, which starts once either figure passes the block
	// fraction of its limit and ends once both fall below the resume fraction. Every index with a copy on
	// the node refuses inserts and updates with `CLUSTER_WRITE_BLOCKED` while it holds.
	Full bool `json:"full"`
}

