// VectorIndexConfig: Controls when a vector field moves from a brute-force scan to an HNSW graph, and
// how that graph is built. A small field answers faster from a brute-force scan, so the engine builds
// a graph only once the field holds enough vectors to earn one. Leave every field unset to accept the
// engine's own values.
type VectorIndexConfig struct {
	// The engine promotes the field to an HNSW graph once it holds this many vectors.
	Threshold *float64 `json:"threshold,omitempty"`
	// A selectivity ratio between 0 and 1, defaulting to 0.03. A filtered search whose filter matches a
	// smaller share of the graph's vectors scans just the matches, and one matching a larger share
	// searches the graph. The engine clamps any value outside that range to it.
	FilterThreshold *float64 `json:"filterThreshold,omitempty"`
	// These settings shape the graph: neighbours per node, build-time exploration, and the metric that
	// ranks results.
	HNSWConfig *VectorIndexConfigHNSWConfig `json:"hnswConfig,omitempty"`
	// The engine codes the promoted vectors in this mode. When this is unset, it picks the mode by the
	// field's dimension. Set `none` to rank by the vectors alone. One of `osq8`, `osq4`, `osq2`, `osq1`,
	// `none`.
	Quantization *string `json:"quantization,omitempty"`
	// The engine keeps the field's full-precision vectors here. When this is unset, it picks `disk` under
	// filesystem durability and `memory` on every other engine. One of `memory`, `disk`.
	Storage *string `json:"storage,omitempty"`
}

// VectorIndexConfigHNSWConfig: These settings shape the graph: neighbours per node, build-time
// exploration, and the metric that ranks results.
type VectorIndexConfigHNSWConfig struct {
	// The graph keeps this many neighbours per node.
	M *float64 `json:"m,omitempty"`
	// The engine explores this many candidates as it builds the graph.
	EfConstruction *float64 `json:"efConstruction,omitempty"`
	// This metric ranks the results. One of `cosine`, `dotProduct`, `euclidean`.
	Metric *string `json:"metric,omitempty"`
}

// VectorMaintenanceResponse: The body of `GET /indexes/{name}/vector-maintenance`.
type VectorMaintenanceResponse struct {
	// One entry describes each vector field of the index.
	Fields []VectorMaintenanceResult `json:"fields"`
}

// VectorMaintenanceResult: The state of one vector field, and what maintenance would cost, as
// VectorMaintenanceOperations.vectorMaintenanceStatus reports it. Removing a vector leaves a tombstone
// in the graph, and enough of them slow a search down. Read this to decide when compaction earns its
// cost.
type VectorMaintenanceResult struct {
	// This describes the named vector field.
	FieldName string `json:"fieldName"`
	// Tombstones make up this share of the graph's nodes, from 0 to 1. Before the first build, where
	// VectorMaintenanceResult.graphCount reads 0, the engine divides by the number of stored vectors,
	// because no graph exists yet.
	TombstoneRatio float64 `json:"tombstoneRatio"`
	// The field holds this many HNSW graphs: 0 before the first build and 1 once a graph exists.
	GraphCount float64 `json:"graphCount"`
	// This many vectors wait outside the graph, which a search scans one by one.
	BufferSize float64 `json:"bufferSize"`
	// This stays true while a graph build runs.
	Building bool `json:"building"`
	// This turns true while a rebuild that keeps recall up waits for the node to have room for a second
	// graph beside the one it serves, and false once it starts.
	WaitingForMemory bool `json:"waitingForMemory"`
	// This stays true after a restart while a field kept on disk loads its codes and graph in the
	// background, during which a search reads them from the field's files.
	LoadingFromFiles bool `json:"loadingFromFiles"`
	// VectorMaintenanceOperations.compactVectors would take about this many milliseconds.
	EstimatedCompactMs float64 `json:"estimatedCompactMs"`
	// VectorMaintenanceOperations.optimizeVectors would take about this many milliseconds.
	EstimatedOptimizeMs float64 `json:"estimatedOptimizeMs"`
}

// VectorQueryConfig: Vector-search inputs passed under `QueryParams.vector`. Supply either a raw
// `value` array or a `text` string for auto-embedding; passing both throws `EMBEDDING_CONFIG_INVALID`.
// Result count is governed by the outer query's `limit`, not by any field on this object.
type VectorQueryConfig struct {
	// Name of the schema field that holds the vector to compare against. Must reference a field declared
	// as `vector[N]` in the index schema.
	Field string `json:"field"`
	// Raw query vector, given as a number array or a `Float32Array`. Length must match the indexed field's
	// dimension or the search rejects the request with `VECTOR_DIMENSION_MISMATCH`.
	Value []float64 `json:"value,omitzero"`
	// Text to embed at query time using the index or instance embedding adapter. Mutually exclusive with
	// `value`; requires a configured adapter.
	Text *string `json:"text,omitempty"`
	// Score floor applied during ranking. Hits scoring below this value are dropped before `limit` is
	// enforced, so the returned hit count can be smaller than `limit` even when more documents exist. The
	// floor is interpreted in score space for every metric; for `euclidean`, distance is mapped to a
	// similarity score of `1 / (1 + distance)` first. Defaults to no floor.
	Similarity *float64 `json:"similarity,omitempty"`
	// Similarity metric used for ranking. Defaults to `cosine`. Choose `dotProduct` for raw inner-product
	// scoring on already-normalised vectors and `euclidean` for distance-based ordering. One of `cosine`,
	// `dotProduct`, `euclidean`.
	Metric *string `json:"metric,omitempty"`
	// The engine keeps this many candidates as it walks the HNSW graph, so a higher value can find more of
	// the true neighbours, although each query takes longer. The engine applies it only once the field
	// holds a graph. The engine fetches k hits, where k is one more than the number of hits up to the end
	// of the page, so k is `limit` plus 1 on a first page. When a query leaves `efSearch` unset, the
	// engine keeps the larger of 50 and k plus a margin, where the margin is 50 below 768 dimensions, 75
	// from 768 to 1,023 dimensions, and 0 at 1,024 dimensions and above. Under a filter, the engine counts
	// only the candidates that pass the filter.
	EfSearch *float64 `json:"efSearch,omitempty"`
	// The engine re-scores this many times k candidates in a quantized field against the full-precision
	// vectors before it returns the best `limit`, where k is one more than the number of hits up to the
	// end of the page, so k is `limit` plus 1 on a first page. For a value below 1, or for a value that is
	// not a finite number, the engine throws a `NarsilError` with code `CONFIG_INVALID`. The engine
	// ignores it on a field whose quantization is `none`. When a query leaves it unset, the engine sets
	// the number of candidates that it re-scores from k and from the field's dimension. It rounds that
	// number up, and it re-scores at least 3k candidates under `osq1` and `osq2`, and at least k under
	// `osq4` and `osq8`. Below 768 dimensions, it re-scores 3.23k + 55.9√k under `osq1` and 2.6k +
	// 22.5√k under `osq2`. From 768 to 1,023 dimensions, it re-scores 2.2k + 27√k under `osq1` and k +
	// 16√k under `osq2`, and under `osq2` it re-scores at least the smaller of k + 75 and k + 18√k. At
	// 1,024 dimensions and above, it re-scores 3k under both. Under `osq4`, it re-scores 5k below 1,024
	// dimensions and 2k from 1,024 dimensions, while under `osq8` it re-scores 2k at every dimension.
	// Under a filter, the engine counts only the candidates that pass the filter. On vectors spread evenly
	// across every dimension, a one-bit or two-bit code can find fewer than 95% of the true nearest
	// neighbours at these defaults, so raise `oversample` on a query that needs more of them.
	Oversample *float64 `json:"oversample,omitempty"`
}

